# Generated by Descant: acceptance tests.

# frozen_string_literal: true

require "rails_helper"

# Two connections race LocalOwner's locks. Each example pauses one transaction
# while it holds the lock under test, proves the other session waits on it with
# blocked_by?, then releases and checks the answers and the committed rows.
RSpec.describe Timekeeping::LocalOwner, "with competing writers", committed_data: true do
  let(:company) { create(:company) }
  let(:employee) { create(:user) }
  let(:project) { create(:project, client: create(:client, company:)) }
  let!(:actor) { described_class::Actor.user(user_id: employee.id, role: "employee") }

  before do
    # The committed-data reset leaves ownership with the legacy store, which
    # LocalOwner refuses as stale_generation.
    TimekeepingOwnership.current.update!(owner: "monolith", monolith_store: "prepared", handoff_step: nil)
    create(:employment, company:, user: employee)
    employee.add_role("employee", company)
  end

  # Read once on the test's own thread, before any handoff can change it.
  let!(:generation) { TimekeepingOwnership.current.generation }

  def stored_entry(note)
    Timekeeping::LocalEntry.create!(
      company_id: company.id, user_id: employee.id, project_id: project.id, work_date: Date.current,
      duration: 30.0, note:, bill_status: "unbilled"
    )
  end

  def update_note(entry, key, note, checkpoint: ->(_step) { })
    described_class.call(
      operation: :update, company_id: entry.company_id, generation: generation.to_s,
      actor:, params: { "idempotency_key" => key, "entry_id" => entry.id, "body" => { "note" => note } }, checkpoint:
    )
  end

  # The step is taken from LocalOwner::STEPS, so renaming it fails here
  # instead of leaving a pause that never fires.
  def pause_at(step_name, entered, release)
    step = described_class::STEPS.find { |candidate| candidate == step_name }
    raise ArgumentError, "#{step_name} is not a LocalOwner step" if step.nil?

    lambda do |reached|
      next unless reached == step

      entered << true
      release.pop
    end
  end

  # Opens a transaction on its own connection that inserts a reservation for
  # the entry and holds it until finish is popped. The foreign key from
  # reservations to entries makes the insert hold a key-share lock on the
  # entry row, which a FOR UPDATE row lock must wait for.
  def hold_reservation_insert(entry, pids, inserted, finish, roll_back:)
    committed_data_thread(pids) do
      ActiveRecord::Base.transaction do
        ApplicationRecord.connection.execute(ApplicationRecord.sanitize_sql_array([<<~SQL.squish, entry.company_id, entry.id, 1, SecureRandom.uuid]))
          INSERT INTO reservations (company_id, entry_id, invoice_id, operation_id, state, disposition, created_at)
          VALUES (?, ?, ?, ?, 'committed', 'active', NOW())
        SQL
        inserted << true
        finish.pop
        raise ActiveRecord::Rollback if roll_back
      end
    end
  end

  def committed_row_count(table)
    ActiveRecord::Base.connection.select_value("SELECT COUNT(*) FROM #{table}").to_i
  end

  def handoff_step
    TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID).handoff_step
  end

  it "refuses to pause at a step LocalOwner does not have" do
    expect { pause_at(:no_such_step, Queue.new, Queue.new) }.to raise_error(ArgumentError, /not a LocalOwner step/)
  end

  # "a handoff waits until LocalOwner commits"
  # The writer pauses after its generation check, while it holds the share
  # lock on the ownership row; that lock is the only one the handoff needs.
  it "makes a handoff update wait until a LocalOwner update paused after the generation check commits" do
    entry = stored_entry("before")
    entered = Queue.new
    release = Queue.new
    writer_pids = Queue.new
    handoff_pids = Queue.new
    checkpoint = pause_at(:generation_checked, entered, release)

    writer = committed_data_thread(writer_pids) { update_note(entry, "handoff-race", "after", checkpoint:) }
    expect(entered.pop(timeout: 5)).to be(true), "the write never paused after its generation check"

    handoff = committed_data_thread(handoff_pids) do
      TimekeepingOwnership.where(id: TimekeepingOwnership::SINGLETON_ID).update_all(handoff_step: "close_admission")
    end

    begin
      blocked = blocked_by?(handoff_pids.pop(timeout: 5), writer_pids.pop(timeout: 5))
      step_while_paused = handoff_step
    ensure
      release << true
    end

    expect(blocked).to be(true), "the handoff never waited on the write's share lock on the ownership row"
    expect(step_while_paused).to be_nil
    expect(writer.join(5)&.value&.status).to eq(200)
    expect(handoff.join(5)).not_to be_nil
    entry.reload
    expect([entry.note, entry.version]).to eq(["after", 2])
    expect(Timekeeping::LocalOutboxEntry.where(entry_id: entry.id).pluck(:generation)).to eq([generation])
    expect(handoff_step).to eq("close_admission")
  ensure
    release&.push(true)
    [writer, handoff].compact.each { |thread| thread.join(5) }
  end

  # "Test the generation lock during a concurrent handoff."
  # The handoff updates the ownership row first and holds its transaction open.
  # A write that acted on its pre-wait snapshot would be admitted past the fence.
  it "refuses a LocalOwner update that queued behind an uncommitted handoff once the handoff commits" do
    entry = stored_entry("before")
    before = entry.reload.attributes
    updated = Queue.new
    commit = Queue.new
    handoff_pids = Queue.new
    writer_pids = Queue.new

    handoff = committed_data_thread(handoff_pids) do
      ActiveRecord::Base.transaction do
        TimekeepingOwnership.where(id: TimekeepingOwnership::SINGLETON_ID).update_all(handoff_step: "close_admission")
        updated << true
        commit.pop
      end
    end
    expect(updated.pop(timeout: 5)).to be(true), "the handoff update never started"

    writer = committed_data_thread(writer_pids) { update_note(entry, "fenced", "after") }

    begin
      blocked = blocked_by?(writer_pids.pop(timeout: 5), handoff_pids.pop(timeout: 5))
    ensure
      commit << true
    end

    expect(blocked).to be(true), "the write never waited on the uncommitted handoff"
    handoff.join(5)
    outcome = writer.join(5)&.value
    expect([outcome&.status, outcome&.body]).to eq([409, { "reason" => "stale_generation" }])
    expect(entry.reload.attributes).to eq(before)
    expect(committed_row_count("entry_audits")).to eq(0)
    expect(committed_row_count("entry_outbox_items")).to eq(0)
    expect(committed_row_count("idempotency_records")).to eq(0)
  ensure
    commit&.push(true)
    [handoff, writer].compact.each { |thread| thread.join(5) }
  end

  # "an employee update waiting behind a reservation insert refuses the now-reserved entry"
  # Only the refusal can catch a reservation flag read from the snapshot taken
  # before the row-lock wait: that stale read would answer 200.
  it "refuses an employee update that waited on the row lock behind a reservation insert that then commits" do
    entry = stored_entry("before")
    before = entry.reload.attributes
    inserted = Queue.new
    finish = Queue.new
    reservation_pids = Queue.new
    update_pids = Queue.new

    reservation = hold_reservation_insert(entry, reservation_pids, inserted, finish, roll_back: false)
    expect(inserted.pop(timeout: 5)).to be(true), "the reservation insert never ran"

    update = committed_data_thread(update_pids) { update_note(entry, "reserved-race", "after") }

    begin
      blocked = blocked_by?(update_pids.pop(timeout: 5), reservation_pids.pop(timeout: 5))
    ensure
      finish << true
    end

    expect(blocked).to be(true), "the update never waited on the reservation insert's lock on the entry row"
    reservation.join(5)
    outcome = update.join(5)&.value
    expect([outcome&.status, outcome&.body]).to eq([403, { "reason" => "forbidden" }])
    expect(entry.reload.attributes).to eq(before)
    expect(Timekeeping::LocalEntry.with_reserved.find(entry.id).reserved).to be(true)
    expect(committed_row_count("entry_audits")).to eq(0)
    expect(committed_row_count("entry_outbox_items")).to eq(0)
    expect(committed_row_count("idempotency_records")).to eq(0)
  ensure
    finish&.push(true)
    [reservation, update].compact.each { |thread| thread.join(5) }
  end

  # The control for the refusal above: the same update succeeds when the
  # reservation rolls back, so that refusal comes from the reservation alone.
  it "lets an employee update that waited behind a rolled-back reservation insert change the entry" do
    entry = stored_entry("before")
    inserted = Queue.new
    finish = Queue.new
    reservation_pids = Queue.new
    update_pids = Queue.new

    reservation = hold_reservation_insert(entry, reservation_pids, inserted, finish, roll_back: true)
    expect(inserted.pop(timeout: 5)).to be(true), "the reservation insert never ran"

    update = committed_data_thread(update_pids) { update_note(entry, "unreserved-race", "after") }

    begin
      blocked = blocked_by?(update_pids.pop(timeout: 5), reservation_pids.pop(timeout: 5))
    ensure
      finish << true
    end

    expect(blocked).to be(true), "the update never waited on the reservation insert's lock on the entry row"
    reservation.join(5)
    expect(update.join(5)&.value&.status).to eq(200)
    entry.reload
    expect([entry.note, entry.version]).to eq(["after", 2])
    expect(Timekeeping::LocalEntry.with_reserved.find(entry.id).reserved).to be(false)
    expect(Timekeeping::LocalOutboxEntry.where(entry_id: entry.id).count).to eq(1)
  ensure
    finish&.push(true)
    [reservation, update].compact.each { |thread| thread.join(5) }
  end

  # "a second outbox writer cannot commit past a paused first writer"
  # The writers update different entries with different keys, so the outbox
  # lock is the only lock they share. Position order alone would read
  # [first, second] even without that lock, so the wait and the uncommitted
  # second row are the proof.
  it "holds a second writer's outbox row back until a first writer paused after its outbox insert commits" do
    first_entry = stored_entry("first")
    second_entry = stored_entry("second")
    entered = Queue.new
    release = Queue.new
    first_pids = Queue.new
    second_pids = Queue.new
    checkpoint = pause_at(:outbox_written, entered, release)

    first = committed_data_thread(first_pids) { update_note(first_entry, "outbox-first", "first after", checkpoint:) }
    expect(entered.pop(timeout: 5)).to be(true), "the first write never paused after its outbox insert"

    second = committed_data_thread(second_pids) { update_note(second_entry, "outbox-second", "second after") }

    begin
      blocked = blocked_by?(second_pids.pop(timeout: 5), first_pids.pop(timeout: 5))
      committed_while_paused = committed_row_count("entry_outbox_items")
    ensure
      release << true
    end

    expect(blocked).to be(true), "the second write never waited on the first write's outbox lock"
    expect(committed_while_paused).to eq(0)
    expect(first.join(5)&.value&.status).to eq(200)
    expect(second.join(5)&.value&.status).to eq(200)
    expect(Timekeeping::LocalOutboxEntry.order(:outbox_position).pluck(:entry_id)).to eq([first_entry.id, second_entry.id])
  ensure
    release&.push(true)
    [first, second].compact.each { |thread| thread.join(5) }
  end
end
